"""Generate the offline copy helper from the exact tracked source files."""
from pathlib import Path
import json
root = Path(__file__).resolve().parents[1]
names = ['Code.gs', 'Domain.js', 'Seed.gs', 'Index.html', 'QR.html', 'appsscript.json']
data = json.dumps({name: (root / name).read_text() for name in names}, ensure_ascii=False).replace('</', '<\\/')
html = '''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cài đặt / Cập nhật V2</title><style>body{font:15px/1.6 system-ui;background:#f6f7fa;color:#30313c;max-width:900px;margin:30px auto;padding:20px}section{background:white;border:1px solid #eceef2;border-radius:12px;padding:24px;margin:18px 0}h1,h2{color:#7757d5}h1{font-size:26px}h2{font-size:19px}button{background:#7757d5;color:white;border:0;border-radius:7px;padding:11px 16px;cursor:pointer;margin-right:8px}textarea{width:100%;height:280px;box-sizing:border-box;font:12px/1.5 monospace;border:1px solid #ddd;border-radius:7px;padding:10px}li{margin:9px 0}select{padding:10px;max-width:100%;border:1px solid #ddd;border-radius:7px}small{color:#9295a3}.warn{background:#fff0f3;padding:14px;border-radius:8px;color:#b45268}</style><h1>Quản lý tài sản & vật tư — V2.0.2</h1><p>Gmail thường · Google Sheets · Apps Script. Không cần gói trả phí.</p><section><h2>1. Chọn cài mới hay cập nhật</h2><p><b>Nếu diagnose đã thành công nhưng giao diện lỗi SyntaxError:</b> chỉ thay Index.html bằng bản này, lưu và triển khai Phiên bản mới. Không chạy setup hoặc seedDemo cho riêng bản vá này.</p><p><b>Đã cài bản trước:</b> sao lưu Sheets, mở dự án Apps Script hiện tại, thay toàn bộ mã 5 file. Chạy setup để thêm cột/tab mới, giữ dữ liệu cũ. Xem CAP-NHAT-V2.md.</p><p class="warn"><b>Không chạy seedDemo khi nâng cấp.</b> Không xóa dữ liệu hoặc đổi tiêu đề cột để ép chương trình chạy.</p><p><b>Cài lần đầu:</b> tạo Google Sheets trống → Tiện ích mở rộng → Apps Script. Tạo các file theo bước 2.</p></section><section><h2>2. Sao chép đúng 6 file</h2><p>Chọn từng file. Với file đã có, Ctrl+A trong vùng mã để thay toàn bộ nội dung; không dán nối.</p><select id="files" onchange="choose()"></select><p id="hint"></p><textarea id="source" readonly spellcheck="false"></textarea><p><button onclick="copy()">Sao chép nội dung</button><span id="status" role="status"></span></p><small>Không dán toàn bộ các file vào Code.gs.</small></section><section><h2>3. Chạy setup</h2><ol><li>Lưu tất cả file.</li><li>Chọn hàm setup → Chạy; cấp quyền cho đúng dự án của bạn khi Google hỏi.</li><li>Chỉ khi cài mới và muốn dữ liệu thử: chạy seedDemo để nạp 30 mục và 4 nhân viên.</li></ol><p>Nếu setup báo cấu trúc khác, dừng và gửi thông báo lỗi; không xóa tab. Xem README.md để kiểm tra nghiệp vụ.</p></section><section><h2>4. Triển khai</h2><p><b>Nâng cấp:</b> Triển khai → Quản lý bản triển khai → bút chì → Phiên bản mới → Triển khai. Giữ URL hiện có.</p><p><b>Cài mới:</b> Triển khai → Triển khai mới → Ứng dụng web. Thực thi: Tôi; quyền truy cập: Chỉ mình tôi.</p><p>Mở URL /exec → Cài đặt → kiểm tra tên cơ sở và URL /exec để QR mở đúng tài sản. Điện thoại cần đăng nhập cùng Gmail. Email và tự lưu PDF chỉ hoạt động sau khi cấu hình/cấp quyền Google. Giao diện 2.0.2 tải mã từ cdn.jsdelivr.net, khóa theo phiên bản và có kiểm tra toàn vẹn; không cần dán App.js vào Apps Script.</p></section><script>const sources=__SOURCES__;const files=document.getElementById('files'),source=document.getElementById('source');Object.keys(sources).forEach(n=>{const o=document.createElement('option');o.value=n;o.textContent=n;files.appendChild(o)});function choose(){source.value=sources[files.value];document.getElementById('hint').textContent=files.value==='Domain.js'?'Script tên Domain (Google hiển thị Domain.gs)':files.value.endsWith('.html')?'HTML tên '+files.value.slice(0,-5):files.value==='appsscript.json'?'Manifest: bật hiển thị appsscript.json trong Cài đặt dự án, rồi thay nội dung file có sẵn.':'Script tên '+files.value.slice(0,-3);document.getElementById('status').textContent=''}async function copy(){source.select();try{await navigator.clipboard.writeText(source.value);document.getElementById('status').textContent='Đã sao chép'}catch(e){document.getElementById('status').textContent=document.execCommand('copy')?'Đã sao chép':'Nhấn Ctrl+C để sao chép phần đang chọn'}}choose();</script></html>'''
(root / 'Bat-dau.html').write_text(html.replace('__SOURCES__', data))
print('Generated Bat-dau.html from current source files')
